<script setup lang="ts">
import {computed,inject,onMounted,ref} from 'vue';
import {Fingerprint,Save,ShieldCheck} from '@lucide/vue';
import {api} from '../../lib/api';
import {adminSessionKey,displayDate,messageOf} from './helpers';
import AdminState from './AdminState.vue';
import AdminModal from './AdminModal.vue';
type PrivacyStatus='received'|'verifying'|'in_progress'|'completed'|'rejected';
type PrivacyRequest={id:string;type:string;status:PrivacyStatus;email:string;fullName:string;message:string;reference?:string;createdAt:string;updatedAt:string;note?:string};
const statusOptions:{id:PrivacyStatus;label:string}[]=[{id:'received',label:'התקבלה'},{id:'verifying',label:'באימות זהות'},{id:'in_progress',label:'בטיפול'},{id:'completed',label:'הושלמה'},{id:'rejected',label:'נדחתה'}];
const requestTypes:Record<string,string>={access:'עיון במידע',correction:'תיקון מידע',deletion:'מחיקת מידע',delete:'מחיקת מידע',other:'אחר'};
const session=inject(adminSessionKey)!,requests=ref<PrivacyRequest[]>([]),loading=ref(true),error=ref(''),success=ref(''),filter=ref(''),selected=ref<PrivacyRequest|null>(null),status=ref<PrivacyStatus>('received'),note=ref(''),busy=ref(false),modalError=ref('');
const filtered=computed(()=>requests.value.filter(r=>!filter.value||r.status===filter.value));
async function load(){const result=await api<{requests:PrivacyRequest[]}>('/api/admin/privacy-requests');requests.value=result.requests;}
function open(request:PrivacyRequest){selected.value=request;status.value=request.status;note.value=request.note||'';modalError.value='';}
async function save(){busy.value=true;modalError.value='';try{await api('/api/admin/privacy-requests',{method:'PATCH',body:JSON.stringify({id:selected.value?.id,status:status.value,note:note.value})});await load();selected.value=null;success.value='סטטוס הבקשה וההערה הפנימית נשמרו.';}catch(e){modalError.value=messageOf(e);}finally{busy.value=false;}}
onMounted(()=>{if(session.role!=='administrator'){loading.value=false;return;}void load().catch(e=>{error.value=messageOf(e);}).finally(()=>{loading.value=false;});});
</script>
<template><div v-if="session.role!=='administrator'" class="admin-panel"><AdminState title="הגישה מוגבלת למנהלי מערכת" description="בקשות פרטיות כוללות מידע רגיש וזמינות למנהלי מערכת בלבד."/></div><template v-else><div class="admin-page-heading"><div><span class="admin-eyebrow">טיפול בפניות מידע</span><h1>בקשות פרטיות</h1><p>מעקב אחר בקשות לעיון, תיקון ומחיקה של מידע שנמסר לארגון.</p></div></div><div v-if="error" class="admin-error" role="alert">{{error}}</div><div v-if="success" class="admin-success" role="status">{{success}}</div><div class="admin-info"><ShieldCheck :size="19"/><span>יש לאמת את זהות הפונה ולבדוק את מדיניות השמירה לפני מסירת מידע או שינויו. שינוי סטטוס אינו מוחק מידע אוטומטית.</span></div><section class="admin-panel"><header class="admin-panel-header"><h2><Fingerprint :size="19"/>כל הבקשות <span class="admin-count">{{requests.length}}</span></h2><select v-model="filter" class="select admin-narrow-select" aria-label="סינון לפי סטטוס"><option value="">כל הסטטוסים</option><option v-for="option in statusOptions" :key="option.id" :value="option.id">{{option.label}}</option></select></header><AdminState v-if="loading" loading/><div v-else-if="filtered.length" class="table-wrap"><table class="data-table"><thead><tr><th>התקבלה</th><th>שם הפונה</th><th>סוג הבקשה</th><th>מספר דיווח</th><th>סטטוס</th><th>פעולות</th></tr></thead><tbody><tr v-for="request in filtered" :key="request.id"><td>{{displayDate(request.createdAt)}}</td><td>{{request.fullName}}<small dir="ltr">{{request.email}}</small></td><td>{{requestTypes[request.type]||request.type}}</td><td>{{request.reference||'לא צוין'}}</td><td><span :class="['status-badge',request.status==='completed'?'status-green':request.status==='rejected'?'status-gray':'status-blue']">{{statusOptions.find(s=>s.id===request.status)?.label}}</span></td><td><button class="btn btn-ghost" @click="open(request)">פתיחה וטיפול</button></td></tr></tbody></table></div><AdminState v-else title="אין בקשות להצגה" description="בקשות שיישלחו מטופס הפרטיות יופיעו כאן."/></section>
<AdminModal v-if="selected" title="טיפול בבקשת פרטיות" :busy="busy" @close="!busy&&(selected=null)"><form @submit.prevent="save"><div class="admin-modal-body"><div v-if="modalError" class="admin-error" role="alert">{{modalError}}</div><dl class="admin-details-grid"><div v-for="[label,value] in [['שם הפונה',selected.fullName],['סוג הבקשה',requestTypes[selected.type]||selected.type],['דוא״ל',selected.email],['מספר דיווח',selected.reference||'לא צוין']]" :key="label" class="admin-data-item"><dt>{{label}}</dt><dd dir="auto">{{value}}</dd></div></dl><div class="admin-privacy-message"><strong>תוכן הבקשה</strong><p>{{selected.message}}</p></div><label class="field"><span class="field-label">סטטוס הטיפול</span><select v-model="status" class="select"><option v-for="option in statusOptions" :key="option.id" :value="option.id">{{option.label}}</option></select></label><label class="field"><span class="field-label">הערה פנימית</span><textarea v-model="note" class="textarea" rows="4" maxlength="4000" placeholder="אימות זהות, בדיקות והמשך טיפול…"/></label><p class="admin-field-hint">העדכון נשמר במערכת. יש להשלים מענה לפונה וטיפול בפועל במידע לפי נוהל הארגון.</p></div><div class="admin-modal-footer"><button class="btn btn-secondary" type="button" :disabled="busy" @click="selected=null">סגירה</button><button class="btn btn-primary" :disabled="busy"><Save :size="16"/>שמירת הטיפול</button></div></form></AdminModal></template></template>
